+            },
+            "category":   { "type": "keyword" },
+            "route":      { "type": "long" },
+            "name":       { "type": "keyword" },
+            "location":   { "type": "geo_point" },
+            "@timestamp": { "type": "date" }
+        }
+    },
+    "settings": {
+        "index": {
+            "mode": "time_series",
+            "routing_path": [ "city" ],
+            "time_series": {
+                "start_time": "2023-01-01T00:00:00Z",
+                "end_time": "2024-01-01T00:00:00Z"
+            }
+        }
+    }
+}
