+                                RestStatus.REQUEST_TIMEOUT
+                            )
+                        );
+                    }
+                )
+            );
+        }
+    }
+
+    @Override
+    protected ClusterBlockException checkBlock(Request request, ClusterState state) {
+        return state.blocks().globalBlockedException(ClusterBlockLevel.METADATA_READ);
+    }
