+              "type": "LineString"
+            },
+            "properties": {
+              "complete": true
+            }
+          }
+        },
+        {
+          "key": "Paris",
+          "doc_count": 2,
+          "museum_tour": {
+            "type": "Feature",
+            "geometry": {
+              "coordinates": [ [ 2.336389, 48.861111 ], [ 2.327, 48.86 ] ],
